#!/usr/bin/env python3
"""Small, dependency-free CSV filtering and aggregation CLI."""

import argparse
import csv
import json
import sys
from decimal import Decimal, InvalidOperation, localcontext
from pathlib import Path


class InputError(Exception):
    """An error in the input file or command-line query."""


def parser() -> argparse.ArgumentParser:
    result = argparse.ArgumentParser(description="Filter and aggregate a CSV file")
    result.add_argument("input", type=Path, help="input CSV file")
    result.add_argument("--where", action="append", default=[], metavar="COLUMN=VALUE")
    result.add_argument("--group-by", metavar="COLUMN")
    result.add_argument("--sum", dest="sum_column", metavar="COLUMN")
    result.add_argument("--avg", dest="avg_column", metavar="COLUMN")
    result.add_argument("--output", choices=("json", "csv"), default="json")
    return result


def parse_filters(raw_filters: list[str]) -> list[tuple[str, str]]:
    filters = []
    for raw in raw_filters:
        if "=" not in raw:
            raise InputError(f"malformed filter {raw!r}; expected COLUMN=VALUE")
        column, value = raw.split("=", 1)
        if not column:
            raise InputError(f"malformed filter {raw!r}; column name is empty")
        filters.append((column, value))
    return filters


def read_csv(path: Path) -> tuple[list[str], list[dict[str, str]], list[int]]:
    try:
        handle = path.open("r", encoding="utf-8", newline="")
    except (OSError, UnicodeError) as exc:
        raise InputError(f"cannot read {path}: {exc}") from exc

    with handle:
        reader = csv.reader(handle, strict=True)
        try:
            headers = next(reader)
        except StopIteration as exc:
            raise InputError("input CSV is empty; a header is required") from exc
        except csv.Error as exc:
            raise InputError(f"malformed CSV header: {exc}") from exc

        if any(header == "" for header in headers):
            raise InputError("headers must be non-empty")
        if len(set(headers)) != len(headers):
            raise InputError("headers must be unique")

        rows = []
        row_numbers = []
        for number, fields in enumerate(reader, start=2):
            if len(fields) != len(headers):
                raise InputError(
                    f"row {number} has {len(fields)} fields; expected {len(headers)}"
                )
            rows.append(dict(zip(headers, fields)))
            row_numbers.append(number)
    return headers, rows, row_numbers


def decimal_string(value: Decimal) -> str:
    """Render a Decimal without exponent notation or redundant zeroes."""
    rendered = format(value, "f")
    if "." in rendered:
        rendered = rendered.rstrip("0").rstrip(".")
    if rendered in ("", "-0"):
        return "0"
    return rendered


def aggregate(
    headers: list[str],
    rows: list[dict[str, str]],
    row_numbers: list[int],
    group_column: str,
    sum_column: str | None,
    avg_column: str | None,
) -> tuple[list[str], list[dict[str, str]]]:
    grouped: dict[str, list[tuple[int, dict[str, str]]]] = {}
    for number, row in zip(row_numbers, rows):
        grouped.setdefault(row[group_column], []).append((number, row))

    output_headers = [group_column]
    if sum_column:
        output_headers.append(f"sum_{sum_column}")
    if avg_column:
        output_headers.append(f"avg_{avg_column}")

    output = []
    for group_value in sorted(grouped):
        members = grouped[group_value]
        values: dict[str, list[Decimal]] = {}
        for column in (sum_column, avg_column):
            if column and column not in values:
                parsed = []
                for number, row in members:
                    raw = row[column]
                    if not raw.strip():
                        raise InputError(
                            f"row {number}, column {column!r}: blank numeric value"
                        )
                    try:
                        value = Decimal(raw)
                    except InvalidOperation as exc:
                        raise InputError(
                            f"row {number}, column {column!r}: invalid numeric value {raw!r}"
                        ) from exc
                    if not value.is_finite():
                        raise InputError(
                            f"row {number}, column {column!r}: invalid numeric value {raw!r}"
                        )
                    parsed.append(value)
                values[column] = parsed

        result = {group_column: group_value}
        if sum_column:
            result[f"sum_{sum_column}"] = decimal_string(sum_decimal(values[sum_column]))
        if avg_column:
            result[f"avg_{avg_column}"] = decimal_string(
                average_decimal(values[avg_column])
            )
        output.append(result)
    return output_headers, output


def decimal_precision(values: list[Decimal]) -> int:
    # Leave enough room for exact addition, including carries across groups.
    return max(28, sum(max(1, len(value.as_tuple().digits)) for value in values) + 10)


def sum_decimal(values: list[Decimal]) -> Decimal:
    with localcontext() as context:
        context.prec = decimal_precision(values)
        total = Decimal(0)
        for value in values:
            total += value
        return +total


def average_decimal(values: list[Decimal]) -> Decimal:
    with localcontext() as context:
        context.prec = max(28, decimal_precision(values))
        return +(sum(values, Decimal(0)) / Decimal(len(values)))


def emit(headers: list[str], rows: list[dict[str, str]], output: str) -> None:
    if output == "json":
        json.dump(rows, sys.stdout, ensure_ascii=False, separators=(",", ":"))
        sys.stdout.write("\n")
    else:
        writer = csv.DictWriter(sys.stdout, fieldnames=headers, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)


def main(argv: list[str] | None = None) -> int:
    args = parser().parse_args(argv)
    try:
        filters = parse_filters(args.where)
        headers, rows, row_numbers = read_csv(args.input)
        requested = [column for column, _ in filters]
        requested += [column for column in (args.group_by, args.sum_column, args.avg_column) if column]
        unknown = [column for column in requested if column not in headers]
        if unknown:
            raise InputError(f"unknown column {unknown[0]!r}")
        if (args.sum_column or args.avg_column) and not args.group_by:
            raise InputError("--sum and --avg require --group-by")

        selected = []
        selected_numbers = []
        for number, row in zip(row_numbers, rows):
            if all(row[column] == value for column, value in filters):
                selected.append(row)
                selected_numbers.append(number)

        if args.sum_column or args.avg_column:
            out_headers, result = aggregate(
                headers, selected, selected_numbers, args.group_by,
                args.sum_column, args.avg_column,
            )
        else:
            out_headers, result = headers, selected
        emit(out_headers, result, args.output)
        return 0
    except InputError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())

